// TestsetRevisionUpsertBulk is the builder for "upsert"-ing
// a bulk of TestsetRevision nodes.
type TestsetRevisionUpsertBulk struct {
	create *TestsetRevisionCreateBulk
}

// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.TestsetRevision.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(testsetrevision.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *TestsetRevisionUpsertBulk) UpdateNewValues() *TestsetRevisionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(testsetrevision.FieldID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(testsetrevision.FieldCreatedAt)
			}
			if _, exists := b.mutation.ProblemID(); exists {
				s.SetIgnore(testsetrevision.FieldProblemID)
			}
			if _, exists := b.mutation.RevisionNumber(); exists {
				s.SetIgnore(testsetrevision.FieldRevisionNumber)
			}
			if _, exists := b.mutation.Checksum(); exists {
				s.SetIgnore(testsetrevision.FieldChecksum)
			}
			if _, exists := b.mutation.TestCount(); exists {
				s.SetIgnore(testsetrevision.FieldTestCount)
			}
			if _, exists := b.mutation.TotalUncompressedBytes(); exists {
				s.SetIgnore(testsetrevision.FieldTotalUncompressedBytes)
			}
			if _, exists := b.mutation.CreatedBy(); exists {
				s.SetIgnore(testsetrevision.FieldCreatedBy)
			}
		}
	}))
	return u
}

// Ignore sets each column to itself in case of conflict.
// Using this option is equivalent to using:
//
//	client.TestsetRevision.Create().
